      const weatherBadge = run.activeWeather === "rain" ? "\u{1F327}\uFE0F Regen" : run.activeWeather === "snow" ? "\u2744\uFE0F Schnee" : run.isNight ? "\u{1F319} Nacht" : "\u2600\uFE0F Klar";
